import * as THREE from 'three';
import { QualityMode } from '@opengolfsim/fuse';

// ============================================================================
// AAA Procedural Texture Generators (Zero Dependencies / 100% Offline)
// ============================================================================

let cachedFairwayTextures: { map: THREE.CanvasTexture; normalMap: THREE.CanvasTexture } | null = null;
let cachedTeeTextures: { map: THREE.CanvasTexture; normalMap: THREE.CanvasTexture } | null = null;
let cachedTableTexture: THREE.CanvasTexture | null = null;

/**
 * Creates high-fidelity fairway turf texture with realistic mowing stripes,
 * micro-blade stippling, and a matching surface normal map.
 */
export function getProceduralFairwayTextures(anisotropy: number = 8): {
  map: THREE.CanvasTexture;
  normalMap: THREE.CanvasTexture;
} {
  if (cachedFairwayTextures) {
    cachedFairwayTextures.map.anisotropy = anisotropy;
    cachedFairwayTextures.normalMap.anisotropy = anisotropy;
    return cachedFairwayTextures;
  }

  const size = 512;
  // 1. Diffuse / Albedo Map
  const colorCanvas = document.createElement('canvas');
  colorCanvas.width = size;
  colorCanvas.height = size;
  const ctx = colorCanvas.getContext('2d')!;

  // Base grass gradient
  const grad = ctx.createLinearGradient(0, 0, 0, size);
  grad.addColorStop(0, '#12662c');
  grad.addColorStop(0.5, '#168038');
  grad.addColorStop(1, '#12662c');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  // Mowing stripes (alternating light / dark grass rows)
  const stripeWidth = size / 4;
  for (let x = 0; x < size; x += stripeWidth) {
    const isLight = (x / stripeWidth) % 2 === 0;
    ctx.fillStyle = isLight ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.09)';
    ctx.fillRect(x, 0, stripeWidth, size);
  }

  // Micro-blade stippling noise
  const imgData = ctx.getImageData(0, 0, size, size);
  const data = imgData.data;
  for (let i = 0; i < data.length; i += 4) {
    const noise = (Math.random() - 0.5) * 26;
    data[i] = Math.min(255, Math.max(0, data[i] + noise * 0.7));     // R
    data[i + 1] = Math.min(255, Math.max(0, data[i + 1] + noise));   // G (vibrant)
    data[i + 2] = Math.min(255, Math.max(0, data[i + 2] + noise * 0.5)); // B
  }
  ctx.putImageData(imgData, 0, 0);

  const diffuseTexture = new THREE.CanvasTexture(colorCanvas);
  diffuseTexture.wrapS = THREE.RepeatWrapping;
  diffuseTexture.wrapT = THREE.RepeatWrapping;
  diffuseTexture.anisotropy = anisotropy;

  // 2. Normal Map (Sobel filter of grass blade heightfield)
  const normCanvas = document.createElement('canvas');
  normCanvas.width = size;
  normCanvas.height = size;
  const nCtx = normCanvas.getContext('2d')!;
  const normData = nCtx.createImageData(size, size);
  const nD = normData.data;

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const idx = (y * size + x) * 4;
      // Procedural pseudo-blade height
      const hL = ((data[(y * size + ((x - 1 + size) % size)) * 4 + 1] / 255) || 0.5);
      const hR = ((data[(y * size + ((x + 1) % size)) * 4 + 1] / 255) || 0.5);
      const hD = ((data[(((y - 1 + size) % size) * size + x) * 4 + 1] / 255) || 0.5);
      const hU = ((data[(((y + 1) % size) * size + x) * 4 + 1] / 255) || 0.5);

      const dx = (hL - hR) * 1.8;
      const dy = (hD - hU) * 1.8;
      const dz = 1.0;
      const len = Math.sqrt(dx * dx + dy * dy + dz * dz);

      nD[idx] = Math.round(((dx / len) * 0.5 + 0.5) * 255);     // Normal X
      nD[idx + 1] = Math.round(((dy / len) * 0.5 + 0.5) * 255); // Normal Y
      nD[idx + 2] = Math.round(((dz / len) * 0.5 + 0.5) * 255); // Normal Z
      nD[idx + 3] = 255;
    }
  }
  nCtx.putImageData(normData, 0, 0);

  const normalTexture = new THREE.CanvasTexture(normCanvas);
  normalTexture.wrapS = THREE.RepeatWrapping;
  normalTexture.wrapT = THREE.RepeatWrapping;
  normalTexture.anisotropy = anisotropy;

  cachedFairwayTextures = { map: diffuseTexture, normalMap: normalTexture };
  return cachedFairwayTextures;
}

/**
 * Creates heavy woven turf hitting mat texture
 */
export function getProceduralTeeTextures(anisotropy: number = 8): {
  map: THREE.CanvasTexture;
  normalMap: THREE.CanvasTexture;
} {
  if (cachedTeeTextures) {
    cachedTeeTextures.map.anisotropy = anisotropy;
    cachedTeeTextures.normalMap.anisotropy = anisotropy;
    return cachedTeeTextures;
  }

  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  ctx.fillStyle = '#0f4822';
  ctx.fillRect(0, 0, size, size);

  // Woven artificial turf grid
  ctx.strokeStyle = 'rgba(20, 80, 40, 0.4)';
  ctx.lineWidth = 1.5;
  for (let i = 0; i < size; i += 6) {
    ctx.beginPath();
    ctx.moveTo(i, 0);
    ctx.lineTo(i, size);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(0, i);
    ctx.lineTo(size, i);
    ctx.stroke();
  }

  // Edge border
  ctx.strokeStyle = '#1e293b';
  ctx.lineWidth = 8;
  ctx.strokeRect(4, 4, size - 8, size - 8);

  const diffTex = new THREE.CanvasTexture(canvas);
  diffTex.wrapS = THREE.RepeatWrapping;
  diffTex.wrapT = THREE.RepeatWrapping;
  diffTex.anisotropy = anisotropy;

  cachedTeeTextures = { map: diffTex, normalMap: diffTex };
  return cachedTeeTextures;
}

/**
 * Creates high-gloss acrylic tournament table surface texture with subtle carbon/grid pattern
 */
export function getProceduralTableTexture(): THREE.CanvasTexture {
  if (cachedTableTexture) return cachedTableTexture;

  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;

  // Deep dark carbon-blue lacquer
  ctx.fillStyle = '#0b1120';
  ctx.fillRect(0, 0, size, size);

  // Fine tournament grid pattern
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.08)';
  ctx.lineWidth = 1;
  for (let i = 0; i < size; i += 16) {
    ctx.beginPath();
    ctx.moveTo(i, 0);
    ctx.lineTo(i, size);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(0, i);
    ctx.lineTo(size, i);
    ctx.stroke();
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  cachedTableTexture = tex;
  return tex;
}

// ============================================================================
// AAA Stadium Sky Dome & Atmosphere
// ============================================================================

export interface StadiumAtmosphere {
  skyDome: THREE.Mesh;
  stars: THREE.Points;
  volumetricBeams: THREE.Group;
  skyTexture: THREE.CanvasTexture;
}

let cachedSkyTexture: THREE.CanvasTexture | null = null;

/**
 * Generates a high-resolution, vivid stadium night sky texture with horizon floodlight glow,
 * deep indigo twilight, and a sparkling crisp starfield.
 */
export function getProceduralNightSkyTexture(): THREE.CanvasTexture {
  if (cachedSkyTexture) return cachedSkyTexture;

  const w = 2048;
  const h = 1024;
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext('2d')!;

  // 1. Deep space night sky gradient (Horizon at y=0, Zenith at y=h)
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0.0, '#122b68'); // Horizon: Electric stadium night glow
  grad.addColorStop(0.06, '#183884'); // Stadium light halo backscatter
  grad.addColorStop(0.18, '#0d1d4a'); // Deep twilight blue
  grad.addColorStop(0.40, '#071029'); // Midnight navy
  grad.addColorStop(0.70, '#030714'); // Cosmic space
  grad.addColorStop(1.0, '#01040a'); // Zenith: Deep starry void
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, w, h);

  // 2. Stadium Floodlight Bank Halos along the horizon
  const floodlightCount = 12;
  for (let i = 0; i < floodlightCount; i++) {
    const fx = (i / floodlightCount) * w + (w / floodlightCount) * 0.5;
    const fy = h * 0.03;
    const fGrad = ctx.createRadialGradient(fx, fy, 2, fx, fy, 160);
    fGrad.addColorStop(0.0, 'rgba(254, 240, 138, 0.45)'); // Warm floodlight core
    fGrad.addColorStop(0.25, 'rgba(56, 189, 248, 0.25)'); // Electric cyan/white halo
    fGrad.addColorStop(0.7, 'rgba(18, 43, 104, 0.1)');
    fGrad.addColorStop(1.0, 'rgba(0, 0, 0, 0.0)');

    ctx.fillStyle = fGrad;
    ctx.beginPath();
    ctx.arc(fx, fy, 160, 0, Math.PI * 2);
    ctx.fill();
  }

  // 3. Crisp Sparkling Starfield (from above horizon up to zenith)
  const starCount = 650;
  for (let i = 0; i < starCount; i++) {
    const sx = Math.random() * w;
    const sy = (0.10 + Math.pow(Math.random(), 0.85) * 0.90) * h;
    const radius = 0.8 + Math.random() * 2.2;
    const brightness = 0.6 + Math.random() * 0.4;

    // Star glow
    if (radius > 1.4) {
      const sGrad = ctx.createRadialGradient(sx, sy, 0, sx, sy, radius * 3.5);
      sGrad.addColorStop(0.0, `rgba(255, 255, 255, ${brightness})`);
      sGrad.addColorStop(0.35, `rgba(186, 230, 253, ${brightness * 0.5})`);
      sGrad.addColorStop(1.0, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = sGrad;
      ctx.beginPath();
      ctx.arc(sx, sy, radius * 3.5, 0, Math.PI * 2);
      ctx.fill();
    }

    // Star core point
    ctx.fillStyle = `rgba(255, 255, 255, ${brightness})`;
    ctx.beginPath();
    ctx.arc(sx, sy, radius * 0.75, 0, Math.PI * 2);
    ctx.fill();
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.ClampToEdgeWrapping;
  cachedSkyTexture = tex;
  return tex;
}

/**
 * Builds high-fidelity night stadium sky dome with horizon atmospheric glow,
 * twinkling stars, and volumetric floodlight beams.
 */
export function createStadiumAtmosphere(scene: THREE.Scene, radius: number = 380): StadiumAtmosphere {
  const skyTexture = getProceduralNightSkyTexture();

  // Set scene background so it renders at infinity without far-clip distance issues
  scene.background = skyTexture;

  // 1. Sky Dome Mesh inside active frustum
  const skyGeo = new THREE.SphereGeometry(radius, 32, 24, 0, Math.PI * 2, 0, Math.PI * 0.52);
  const skyMat = new THREE.MeshBasicMaterial({
    map: skyTexture,
    side: THREE.BackSide,
    depthWrite: false,
  });

  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  scene.add(skyDome);

  // 2. Twinkling Night Stars Points
  const starCount = 400;
  const starGeo = new THREE.BufferGeometry();
  const starPositions = new Float32Array(starCount * 3);
  const starColors = new Float32Array(starCount * 3);

  for (let i = 0; i < starCount; i++) {
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(Math.random() * 0.75 + 0.2);
    const r = radius * 0.95;

    starPositions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    starPositions[i * 3 + 1] = r * Math.cos(phi);
    starPositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);

    const brightness = 0.8 + Math.random() * 0.2;
    starColors[i * 3] = brightness;
    starColors[i * 3 + 1] = brightness * 0.95;
    starColors[i * 3 + 2] = brightness * 1.15;
  }

  starGeo.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
  starGeo.setAttribute('color', new THREE.BufferAttribute(starColors, 3));

  const starMat = new THREE.PointsMaterial({
    size: 3.5,
    vertexColors: true,
    transparent: true,
    opacity: 0.95,
    depthWrite: false,
  });
  const stars = new THREE.Points(starGeo, starMat);
  scene.add(stars);

  // 3. Volumetric Stadium Floodlight Beams
  const volumetricBeams = new THREE.Group();
  scene.add(volumetricBeams);

  return { skyDome, stars, volumetricBeams, skyTexture };
}

/**
 * Creates a subtle volumetric stadium floodlight beam cone shining downward onto the range
 */
export function createVolumetricLightBeam(
  height: number = 14,
  radiusTop: number = 0.5,
  radiusBottom: number = 8.5,
  colorHex: number = 0xfef08a
): THREE.Mesh {
  const coneGeo = new THREE.CylinderGeometry(radiusTop, radiusBottom, height, 8, 1, true);
  coneGeo.translate(0, -height / 2, 0);

  // Set completely transparent so no foggy milky columns block the player's view
  const coneMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(colorHex),
    transparent: true,
    opacity: 0.0,
    visible: false,
  });

  return new THREE.Mesh(coneGeo, coneMat);
}

// ============================================================================
// AAA Visual Effects: Liquid Splash Droplets & Celebration Fireworks
// ============================================================================

export interface Particle {
  pos: THREE.Vector3;
  vel: THREE.Vector3;
  color: THREE.Color;
  size: number;
  life: number;
  maxLife: number;
  gravity: number;
  drag: number;
}

export interface Shockwave {
  mesh: THREE.Mesh;
  life: number;
  maxLife: number;
  startScale: number;
  endScale: number;
  startOpacity: number;
}

export class ArcadeParticleSystem {
  particles: Particle[] = [];
  instancedMesh: THREE.InstancedMesh;
  dummy = new THREE.Object3D();
  maxParticles: number;

  shockwaves: Shockwave[] = [];
  shockwavePool: THREE.Mesh[] = [];
  scene: THREE.Scene;

  constructor(scene: THREE.Scene, maxParticles: number = 1000) {
    this.scene = scene;
    this.maxParticles = maxParticles;

    // 1. High-Performance 3D Instanced Droplets / Sparks
    const sphereGeo = new THREE.SphereGeometry(0.12, 7, 5);
    const instMat = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });

    this.instancedMesh = new THREE.InstancedMesh(sphereGeo, instMat, maxParticles);
    this.instancedMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    if (this.instancedMesh.instanceColor) {
      this.instancedMesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
    }
    this.instancedMesh.frustumCulled = false;
    this.instancedMesh.count = 0;
    scene.add(this.instancedMesh);

    // 2. Shockwave Rings Pool
    const ringGeo = new THREE.RingGeometry(0.08, 0.48, 32);
    ringGeo.rotateX(-Math.PI / 2); // Horizontal ring

    for (let i = 0; i < 8; i++) {
      const ringMat = new THREE.MeshBasicMaterial({
        color: 0xf59e0b,
        transparent: true,
        opacity: 0,
        side: THREE.DoubleSide,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      });
      const ring = new THREE.Mesh(ringGeo, ringMat);
      ring.visible = false;
      scene.add(ring);
      this.shockwavePool.push(ring);
    }
  }

  /**
   * Spawns an expanding horizontal shockwave ring at the contact point
   */
  spawnShockwave(pos: THREE.Vector3, colorHex: number = 0xf59e0b, endScale: number = 2.8, duration: number = 0.65) {
    const ring = this.shockwavePool.find((r) => !r.visible);
    if (!ring) return;

    ring.position.copy(pos);
    ring.scale.set(0.2, 0.2, 0.2);
    (ring.material as THREE.MeshBasicMaterial).color.setHex(colorHex);
    (ring.material as THREE.MeshBasicMaterial).opacity = 0.95;
    ring.visible = true;

    this.shockwaves.push({
      mesh: ring,
      life: 0,
      maxLife: duration,
      startScale: 0.2,
      endScale: endScale,
      startOpacity: 0.95,
    });
  }

  /**
   * Spawns a high-energy liquid beer splash crown with amber droplets, foaming froth, and shockwave
   */
  spawnBeerSplash(origin: THREE.Vector3, count: number = 90, scale: number = 1.0) {
    // 1. Expand glowing shockwave at cup rim
    this.spawnShockwave(origin, 0xf59e0b, 2.5 * scale, 0.6);

    const amber = new THREE.Color(0xf59e0b);
    const gold = new THREE.Color(0xfef08a);
    const foam = new THREE.Color(0xffffff);

    // 2. Eject 3D droplet fountain
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= this.maxParticles) break;

      const angle = Math.random() * Math.PI * 2;
      const spread = 0.2 + Math.random() * 0.8;
      const speed = (2.2 + Math.random() * 4.2) * scale;
      const upward = (3.5 + Math.random() * 5.2) * scale;

      const isFoam = Math.random() < 0.35;
      const color = isFoam ? foam : (Math.random() < 0.55 ? amber : gold);
      const size = (0.09 + Math.random() * 0.16) * Math.min(2.5, scale);

      this.particles.push({
        pos: origin.clone().add(new THREE.Vector3(
          (Math.random() - 0.5) * 0.25 * scale,
          0.02 * scale,
          (Math.random() - 0.5) * 0.25 * scale
        )),
        vel: new THREE.Vector3(
          Math.cos(angle) * spread * speed,
          upward,
          Math.sin(angle) * spread * speed
        ),
        color: color.clone(),
        size: size,
        life: 0,
        maxLife: 0.9 + Math.random() * 0.6,
        gravity: 9.81,
        drag: 0.985,
      });
    }
  }

  /**
   * Spawns celebratory victory fireworks / confetti fountain
   */
  spawnCelebrationFireworks(origin: THREE.Vector3, team: 'red' | 'blue' | 'gold' = 'gold', count: number = 160) {
    const teamHex = team === 'red' ? 0xef4444 : team === 'blue' ? 0x38bdf8 : 0xfbbf24;
    this.spawnShockwave(origin, teamHex, 3.8, 0.85);

    const palette = team === 'red'
      ? [new THREE.Color(0xef4444), new THREE.Color(0xf87171), new THREE.Color(0xfbbf24), new THREE.Color(0xffffff)]
      : team === 'blue'
      ? [new THREE.Color(0x38bdf8), new THREE.Color(0x60a5fa), new THREE.Color(0xa78bfa), new THREE.Color(0xffffff)]
      : [new THREE.Color(0xfacc15), new THREE.Color(0xf59e0b), new THREE.Color(0x38bdf8), new THREE.Color(0xffffff)];

    for (let i = 0; i < count; i++) {
      if (this.particles.length >= this.maxParticles) break;

      const theta = Math.random() * Math.PI * 2;
      const phi = Math.random() * Math.PI * 0.5; // upward hemisphere
      const speed = 4.5 + Math.random() * 8.5;
      const col = palette[Math.floor(Math.random() * palette.length)];

      this.particles.push({
        pos: origin.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.4, 0.3, (Math.random() - 0.5) * 0.4)),
        vel: new THREE.Vector3(
          Math.sin(phi) * Math.cos(theta) * speed,
          Math.cos(phi) * speed + 3.0,
          Math.sin(phi) * Math.sin(theta) * speed
        ),
        color: col.clone(),
        size: 0.16 + Math.random() * 0.22,
        life: 0,
        maxLife: 1.3 + Math.random() * 0.9,
        gravity: 6.8,
        drag: 0.975,
      });
    }
  }

  /**
   * Updates all active particles and shockwaves
   */
  update(delta: number) {
    // 1. Update Shockwave Rings
    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const s = this.shockwaves[i];
      s.life += delta;
      const p = s.life / s.maxLife;

      if (p >= 1.0) {
        s.mesh.visible = false;
        this.shockwaves.splice(i, 1);
        continue;
      }

      const curScale = THREE.MathUtils.lerp(s.startScale, s.endScale, Math.pow(p, 0.65));
      s.mesh.scale.set(curScale, curScale, curScale);
      (s.mesh.material as THREE.MeshBasicMaterial).opacity = s.startOpacity * (1.0 - p);
    }

    // 2. Update 3D Droplet Particles
    let aliveCount = 0;
    const tempColor = new THREE.Color();

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life += delta;

      if (p.life >= p.maxLife) {
        this.particles.splice(i, 1);
        continue;
      }

      // Physics integration
      p.vel.y -= p.gravity * delta;
      p.vel.x *= Math.pow(p.drag, delta * 60);
      p.vel.z *= Math.pow(p.drag, delta * 60);
      p.pos.addScaledVector(p.vel, delta);

      // Bounce lightly off ground
      if (p.pos.y < 0.04) {
        p.pos.y = 0.04;
        p.vel.y = -p.vel.y * 0.32;
      }

      const frac = p.life / p.maxLife;
      const alpha = 1.0 - frac;
      const currentScale = p.size * (1.0 - frac * 0.35);

      this.dummy.position.copy(p.pos);
      this.dummy.scale.set(currentScale, currentScale, currentScale);
      this.dummy.updateMatrix();

      this.instancedMesh.setMatrixAt(aliveCount, this.dummy.matrix);

      tempColor.copy(p.color).multiplyScalar(alpha);
      this.instancedMesh.setColorAt(aliveCount, tempColor);

      aliveCount++;
    }

    this.instancedMesh.count = aliveCount;
    this.instancedMesh.instanceMatrix.needsUpdate = true;
    if (this.instancedMesh.instanceColor) {
      this.instancedMesh.instanceColor.needsUpdate = true;
    }
  }
}
